  <script>
    // التحكم بخانات الإدخال التلقائي والتنقل بينها
    const inputs = document.querySelectorAll('.otp-input');
    const verifyBtn = document.getElementById('verify-button');

    inputs.forEach((input, index) => {
      // إدخال الأرقام فقط والانتقال للخانات التالية
      input.addEventListener('input', (e) => {
        const val = e.target.value.replace(/[^0-9]/g, '');
        e.target.value = val ? val[0] : '';

        if (e.target.value) {
          input.classList.add('filled');
          if (index < inputs.length - 1) {
            inputs[index + 1].focus();
          }
        } else {
          input.classList.remove('filled');
        }
        checkFullCode();
      });

      // التعامل مع الحذف وزر الرجوع Backspace
      input.addEventListener('keydown', (e) => {
        if (e.key === 'Backspace' && !input.value && index > 0) {
          inputs[index - 1].focus();
        }
      });

      // لصق الرمز كاملاً
      input.addEventListener('paste', (e) => {
        e.preventDefault();
        const pastedData = (e.clipboardData || window.clipboardData).getData('text').replace(/\D/g, '').slice(0, 6);
        if (pastedData) {
          pastedData.split('').forEach((char, i) => {
            if (inputs[i]) {
              inputs[i].value = char;
              inputs[i].classList.add('filled');
            }
          });
          const nextIndex = Math.min(pastedData.length, inputs.length - 1);
          inputs[nextIndex].focus();
          checkFullCode();
        }
      });
    });

    function checkFullCode() {
      const code = Array.from(inputs).map(i => i.value).join('');
      // يمكن تفعيل أو تمييز الزر عند اكتمال الرمز
      if (code.length === 6) {
        verifyBtn.style.background = 'linear-gradient(135deg, #004d26 0%, #006C35 100%)';
      }
    }

    // منطق العداد التنازلي (45 ثانية كما هو محدد)
    let timeLeft = 45;
    let timerInterval;
    const timerElem = document.getElementById('timer');
    const timerBox = document.getElementById('timer-box');
    const resendBtn = document.getElementById('resend-btn');

    function startCountdown() {
      clearInterval(timerInterval);
      timeLeft = 45;
      timerBox.style.display = 'inline-flex';
      resendBtn.style.display = 'none';
      updateTimerDisplay();

      timerInterval = setInterval(() => {
        timeLeft--;
        updateTimerDisplay();

        if (timeLeft <= 0) {
          clearInterval(timerInterval);
          timerBox.style.display = 'none';
          resendBtn.style.display = 'inline-block';
        }
      }, 1000);
    }

    function updateTimerDisplay() {
      const minutes = Math.floor(timeLeft / 60);
      const seconds = timeLeft % 60;
      timerElem.textContent = `${minutes}:${seconds < 10 ? '0' : ''}${seconds}`;
    }

    function restartTimer() {
      startCountdown();
      inputs.forEach(i => { i.value = ''; i.classList.remove('filled'); });
      inputs[0].focus();
    }

    // إجراء زر التأكيد
    function handleVerify() {
      const code = Array.from(inputs).map(i => i.value).join('');
      const toast = document.getElementById('toast');

      if (code.length === 6) {
        toast.textContent = 'جاري التحقق من صحة الرمز...';
        toast.style.background = '#006C35';
        toast.classList.add('show');
        setTimeout(() => {
          toast.textContent = 'تم تأكيد العملية المصرفية بنجاح!';
          setTimeout(() => toast.classList.remove('show'), 2000);
        }, 800);
      } else {
        toast.textContent = 'الرجاء إدخال كامل الرمز المكون من 6 أرقام';
        toast.style.background = '#B42318';
        toast.classList.add('show');
        setTimeout(() => toast.classList.remove('show'), 2500);
      }
    }

    // بدء العداد عند فتح الصفحة
    startCountdown();
  </script>
